ALTER TABLE "smpp_events" ADD CONSTRAINT "smpp_events_result_check" CHECK (("smpp_events"."kind" = 'bind' and "smpp_events"."result" in ('ok', 'wrong_password', 'ip_not_allowed', 'disabled', 'product_off', 'client_inactive', 'too_many_sessions', 'ip_blocked', 'unknown_login')) or ("smpp_events"."kind" = 'submit' and "smpp_events"."result" in ('invalid_destination', 'invalid_length', 'invalid_validity', 'wrong_mode', 'rejected', 'throttled', 'system_error', 'recipient_not_in_max', 'recipient_inactive', 'recipient_stopped', 'duplicate_message', 'recipient_limit', 'insufficient_funds', 'requirements_unmet')));